// MISCONCEPTION: volatile does NOT make this thread-safe in C++!
class Singleton {
    static volatile Singleton* volatile pInstance;  // Still unsafe!
};

// volatile only guarantees:
// 1. Reads are not optimized away (value is "unstable")
// 2. Writes are not optimized away ("observable")
// 3. Operations occur in source order (within one thread)

// What volatile DOES NOT guarantee in C++:
// - Atomicity of operations
// - Memory ordering across threads
// - Prevention of race conditions
// - Visibility guarantees across processors/cores

// Legitimate uses of volatile in C++:
volatile int* mmio_register = (int*)0xFFFF0000;  // Memory-mapped I/O
volatile sig_atomic_t signal_flag;               // Signal handlers

// For thread safety, use atomics or mutexes:
std::atomic<Singleton*> pInstance;              // Thread-safe
std::mutex mtx;                                  // Proper synchronization

