#include <iostream>
#include <thread>
#include <atomic>
#include <chrono>

// Demonstrates why volatile is insufficient for threading

class DataRace {
public:
    // UNSAFE: volatile does not prevent data races
    volatile int counter_volatile = 0;

    // SAFE: std::atomic provides proper synchronization
    std::atomic<int> counter_atomic{0};

    void incrementVolatile(int iterations) {
        for (int i = 0; i < iterations; ++i) {
            // NOT atomic! Read-modify-write is three separate operations
            // Race condition: multiple threads can read same value
            counter_volatile++;
        }
    }

    void incrementAtomic(int iterations) {
        for (int i = 0; i < iterations; ++i) {
            // Atomic operation: guaranteed to be indivisible
            counter_atomic.fetch_add(1, std::memory_order_seq_cst);
        }
    }
};

int main() {
    DataRace data;
    const int ITERATIONS = 10000;

    // Test volatile (UNSAFE)
    std::thread t1(&DataRace::incrementVolatile, &data, ITERATIONS);
    std::thread t2(&DataRace::incrementVolatile, &data, ITERATIONS);
    t1.join();
    t2.join();

    std::cout << "Expected: " << (2 * ITERATIONS) << "\n";
    std::cout << "volatile result: " << data.counter_volatile 
              << " (likely wrong due to race condition!)\n";

    // Test atomic (SAFE)
    std::thread t3(&DataRace::incrementAtomic, &data, ITERATIONS);
    std::thread t4(&DataRace::incrementAtomic, &data, ITERATIONS);
    t3.join();
    t4.join();

    std::cout << "atomic result: " << data.counter_atomic.load() 
              << " (correct - thread-safe)\n";

    std::cout << "\nLesson: Use std::atomic or mutexes for thread safety,\n";
    std::cout << "         not volatile! volatile is for MMIO/ISRs only.\n";

    return 0;
}
